const related = (slug: string) => [{ title: 'HR operations support', href: '/services/operations-support', note: 'Review the matching support lane.' }, { title: 'HR reporting and QA', href: '/services/reporting-and-qa', note: 'Plan owner review and evidence.' }, { title: 'HR outsourcing planning guide', href: '/blog/human-resources-outsourced-planning', note: 'Keep the role boundary visible.' }, { title: 'This guide', href: `/blog/${slug}`, note: 'Current workflow.' }];
const source = { name: 'International Labour Organization: Decent work and the care economy', url: 'https://www.ilo.org/topics-and-sectors/care-economy', note: 'General context for clear responsibilities and accountable work arrangements.' };

const makeArticle = (t: Topic, index: number): RichArticle => {
  const paragraphs = routeSourceGuidance[t.slug].body.split('\\n\\n');
  const legacyParagraphs = [
    `A Philippines-based HR support role can prepare and track ${t.focus}, but the useful boundary begins before the first item arrives. Write the accepted source, the fields to record, the approved destination, the reviewer, and the stop condition. The point is not to make the support role sound broad; it is to make one repeatable administrative lane understandable to the person doing it and to the owner checking it.`,
    `The company owner keeps ${t.decision}. Support staff may compare approved records, format a queue, send an approved reminder, and report a missing input. They should not infer an employment outcome, interpret policy, answer a legal question, decide eligibility, investigate a complaint, or change a sensitive record because one value looks more convenient. A handoff should state what is known, what is missing, and who must decide.`,
    `Start with the real case pattern: ${t.case}. Write the first event, the authoritative source, the next allowed action, and the owner who accepts the handoff. Then add the exception path. If the request contains more than the queue needs, keep the minimum detail required for routing and preserve the original in the approved system. The Philippines context matters operationally because remote teams need explicit time-zone, channel, and acknowledgement rules; it does not remove the company owner’s responsibility.`,
    `A strong queue distinguishes received, prepared, waiting, escalated, and closed. Each status needs an observable test. “Prepared” can mean the source was checked and the packet is ready; it cannot mean a judgment was made. “Closed” should require the owner’s response or an approved downstream confirmation. This makes ${t.measure} measurable without turning an administrative count into a claim about employee quality or business results.`,
    `The common failure is ${t.failure}. Prevent it with a source link, a named owner, a due time, and a reason code for exceptions. Preserve conflicting records rather than selecting the tidier one. A second reviewer can check whether the support action stayed inside scope, whether private detail travelled too far, and whether the receiving owner understood the question. Fix the written workflow when the same ambiguity returns.`,
    `Use a small pilot with redacted examples: one ordinary item, one missing field, one conflicting source, one late response, and one restricted request. Ask the owner to watch the stop points. The support role can prepare a comparison and route it; the qualified HR, recruiting, payroll, finance, legal, system, or management owner makes the decision. Do not use a pilot to quietly expand access or authority.`,
    `At review time, compare the queue with the original role brief. Count items that had a source, an owner, an allowed action, a timely handoff, and evidence of closure. Examine misses by cause rather than blaming a person: unclear intake, stale template, missing permission, unavailable owner, or an exception that was never defined. This turns ${t.focus} into an operating routine that can be narrowed, improved, or handed back safely.`,
    `A practical handoff says: “This ${t.focus} item arrived from [source] on [date]. I checked [fields], prepared [allowed output], and found [open question]. Please confirm [decision] by [time].” That language protects meaning and keeps accountability visible. It is especially useful when an employee, candidate, manager, or vendor asks a question that crosses from administration into judgment.`,
    `Do not publish invented company facts, outcomes, credentials, or testimonials around this workflow. Use the company’s actual approved records and qualified advice for the live process. Public guidance can explain controls and role boundaries; it cannot promise a legal result, a payroll result, an eligibility result, or a particular response time without a confirmed operating agreement.`,
    `The decision to expand should be deliberate. Review access, sample quality, unresolved exceptions, owner response, and the privacy of the record. If the queue works only when one person remembers an unwritten rule, it is not ready to scale. If a sensitive issue appears, stop, preserve the minimum necessary context, and route it to the named owner. That is a successful control, not a failure of support.`
  ];
  return { slug:t.slug,title:t.title,description:t.description,published:routeSourceGuidance[t.slug].date,updated:routeSourceGuidance[t.slug].date,minutes:12,revision:`${routeSourceGuidance[t.slug].date}-${t.slug}`,
    directAnswer:[`A Philippines-based HR coordinator can prepare and track ${t.focus} from approved sources. The company’s qualified owner retains ${t.decision}, sensitive conversations, exceptions, and final approval.`,`Begin with one narrow queue, a named reviewer, minimum necessary access, and evidence for each close. Expand only after a sample shows that routine preparation and owner judgment remain separate.`],
    takeaways:[`Define ${t.focus} as a bounded queue.`,`Keep ${t.decision} with the qualified owner.`,`Preserve source evidence and conflicting values.`,`Use explicit stop points for restricted requests.`,`Measure ${t.measure}.`],
    taskRows:[{lane:'Intake',philippinesTeam:`Receive and classify ${t.focus} from the approved channel.`,owner:'Set scope, priority, and accountable owner.',check:'Source, date, and privacy level are visible'},{lane:'Preparation',philippinesTeam:'Check fields and prepare the allowed packet or reminder.',owner:'Approve changes, exceptions, and sensitive wording.',check:'Every output traces to a source'},{lane:'Handoff',philippinesTeam:'Route the open question and record acknowledgement.',owner:'Make the substantive decision.',check:'Recipient and due time are named'},{lane:'Review',philippinesTeam:'Assemble a representative sample and note misses.',owner:'Confirm quality and update the rule.',check:'Correction is recorded'},{lane:'Closeout',philippinesTeam:'Save status and evidence in the approved system.',owner:'Confirm completion and retention.',check:'No unsupported inference is presented as fact'}],
    pilotStats:[{value:'1',label:'Starting lane',note:'Keep the first queue narrow.'},{value:'2',label:'Review passes',note:'Check preparation and handoff.'},{value:'3',label:'Escalation tiers',note:'Routine, owner review, urgent route.'},{value:String(7+index),label:'Test cases',note:'Use varied redacted examples.'}],
    sections:[{heading:`What ${t.focus} should include`,paragraphs:paragraphs.slice(0,2)},{heading:'Build from the actual exception',paragraphs:paragraphs.slice(2,4)},{heading:'Protect the record and the boundary',paragraphs:paragraphs.slice(4,6)},{heading:'Review what the queue proves',paragraphs:paragraphs.slice(6,8)},{heading:'Keep public guidance factually bounded',paragraphs:paragraphs.slice(8,10)}],
    scripts:[{label:'Owner handoff',text:`This ${t.focus} item is prepared from [source]. I checked [fields]. The open question is [question]. Please confirm [decision] and owner.`},{label:'Stop rule',text:`I can prepare and route ${t.focus} from approved sources. I will stop before making a decision, interpreting policy, or answering a restricted question.`}],
    workflow:[{step:'01',title:'Map the source',text:'Name the approved input, required fields, owner, and destination.'},{step:'02',title:'Test the edge',text:'Walk the ordinary, missing, conflicting, late, and restricted cases.'},{step:'03',title:'Run the lane',text:'Prepare routine work and preserve evidence.'},{step:'04',title:'Review the sample',text:'Check routing, access, privacy, and stop points.'},{step:'05',title:'Choose scope',text:'Expand, narrow, or hand back based on the record.'}],
    faqs:[{question:`What can support staff do for ${t.focus}?`,answer:'They can organize, check, prepare, remind, and route approved work. Owners retain decisions, sensitive communications, exceptions, and final approval.'},{question:'What should stay with the company?',answer:'Employment outcomes, policy interpretation, legal questions, pay and benefits decisions, investigations, complaints, and sensitive exceptions.'},{question:'How should conflicting records be handled?',answer:'Preserve both sources, describe the difference, and route the decision to a named qualified owner.'},{question:'What makes the queue complete?',answer:'A source, allowed action, owner, status, date, approval where needed, and evidence are visible.'},{question:'When should the role stop?',answer:'Stop when the request requires judgment, sensitive questioning, policy interpretation, or a decision not supported by the approved source.'}],
    related:related(t.slug),sources:[source],banners:[{eyebrow:'First task',title:'Write the queue before assigning it.',text:`Define inputs, outputs, access, owners, and stop rules for ${t.focus}.`,href:'/services/operations-support',linkLabel:'Review HR operations support'},{eyebrow:'Quality check',title:'Review a representative sample.',text:'Look for missing sources, wrong routing, and assumed approvals.',href:'/services/reporting-and-qa',linkLabel:'See HR reporting and QA'},{eyebrow:'Plan the role',title:'Keep judgment with the owner.',text:'Bring a redacted workflow to a staffing discussion.',href:'/contact-us',linkLabel:'Discuss HR support'}]};
};

